raw_queries.lane_lookups_and_mutations:
query($t: String!, $n: [String!]) { workflowStates(filter: {team: {key: {eq: $t}}}) { nodes { id name } } issueLabels(filter: {name: {in: $n}}) { nodes { id name } } users(filter: {email: {eq: "$KENDEX_USER_EMAIL"}}) { nodes { id } } }
mutation($id: String!, $input: IssueUpdateInput!) { issueUpdate(id: $id, input: $input) { success issue { identifier state { name } } } }
mutation($input: CommentCreateInput!) { commentCreate(input: $input) { success comment { id } } }
